"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def decimalToBinary(n):
    if (n == 0):
        return '0'
    binaryString = ''
    while (n > 0):
        remainder = (n % 2)
        binaryString = (str(remainder) + binaryString)
        n = (n // 2)
    return binaryString
print(decimalToBinary(10))